option.value:
@font-face {
    font-family: "Noto Sans CJK SC";
}

body {
    background-color: white;
    -webkit-text-size-adjust: 100%;
    -fx-text-size-adjust: 100%;
    -ms-text-size-adjust: 100%;
    text-size-adjust: 100%;
    color: #333;
    font-family: "Noto Sans CJK SC";
    font-size: 16px;
    line-height: 1.6;
    word-wrap: break-word;
}

a {
    background-color: transparent;
}

a:active,
a:hover {
    outline: 0;
}

strong {
    font-weight: bold;
}

h1 {
    font-size: 2em;
    margin: 0.67em 0;
}
